import ContextMenu from "@marko-ui/shadcn/ui/context-menu/context-menu.marko";
import type { ContextMenuItem } from "@marko-ui/shadcn/ui/context-menu/context-menu.marko";

<let/showBookmarksBar=true/>
<let/showFullUrls=false/>
<let/showDeveloperTools=true/>

<const/items=[
  { type: "checkbox", value: "bookmarks-bar", label: "Show Bookmarks Bar", checked: showBookmarksBar },
  { type: "checkbox", value: "full-urls", label: "Show Full URLs", checked: showFullUrls },
  { type: "checkbox", value: "developer-tools", label: "Show Developer Tools", checked: showDeveloperTools },
] satisfies ContextMenuItem[]/>

<ContextMenu
  items=items
  select(value) {
    if (value === "bookmarks-bar") showBookmarksBar = !showBookmarksBar;
    else if (value === "full-urls") showFullUrls = !showFullUrls;
    else if (value === "developer-tools") showDeveloperTools = !showDeveloperTools;
  }
>
  <div class="flex h-[100px] w-[250px] items-center justify-center rounded-md border border-dashed text-sm text-muted-foreground">
    Right click here
  </div>
</ContextMenu>

